/* eslint-env node */

import {TextDecoder, TextEncoder} from 'util';
import '@testing-library/jest-dom';

global.TextDecoder = TextDecoder;
global.TextEncoder = TextEncoder;

import React from 'react';
import {act, render} from '@testing-library/react';
import {renderToString} from 'react-dom/server.node';

import * as CheckoutContextModule from './CheckoutContext';
import {CheckoutFormProvider} from './CheckoutFormProvider';
import {CheckoutElementsProvider} from './CheckoutElementsProvider';
import createElementComponent from '../../components/createElementComponent';
import {Elements} from '../../components/Elements';
import {useStripe} from '../../components/useStripe';
import {CheckoutFormProps, PaymentElementProps} from '../../types';
import * as mocks from '../../../test/mocks';
import makeDeferred from '../../../test/makeDeferred';

const providerCases = [
  {
    name: 'CheckoutFormProvider',
    Provider: CheckoutFormProvider,
    useCheckout: CheckoutContextModule.useCheckoutForm,
    initMethod: 'initCheckoutFormSdk' as const,
    createMethod: 'createForm' as const,
    elementType: 'paymentForm' as const,
    initialOptions: {layout: 'expanded' as const},
    updatedOptions: {layout: 'compact' as const},
  },
  {
    name: 'CheckoutElementsProvider',
    Provider: CheckoutElementsProvider,
    useCheckout: CheckoutContextModule.useCheckoutElements,
    initMethod: 'initCheckoutElementsSdk' as const,
    createMethod: 'createPaymentElement' as const,
    elementType: 'payment' as const,
    initialOptions: {layout: 'tabs' as const},
    updatedOptions: {layout: 'accordion' as const},
  },
];

providerCases.forEach(
  ({
    name,
    Provider,
    useCheckout,
    initMethod,
    createMethod,
    elementType,
    initialOptions,
    updatedOptions,
  }) => {
    describe(name, () => {
      // Element and StripeConsumer are memoized to exclude parent-driven renders;
      // context updates still propagate through React.memo.
      const Element = React.memo(
        createElementComponent(elementType, false) as React.FunctionComponent<{
          options?:
            | CheckoutFormProps['options']
            | PaymentElementProps['options'];
          onChange?: (event: unknown) => void;
        }>
      );
      const providerOptions = {clientSecret: 'cs_123'};

      const setup = () => {
        const stripe: any = mocks.mockStripe();
        const sdk = mocks.mockCheckoutSdk();
        const element = {...mocks.mockElement(), off: jest.fn()};
        const actions = mocks.mockCheckoutActions();
        const session = mocks.mockCheckoutSession();
        const loadActions = makeDeferred();
        stripe[initMethod].mockReturnValue(sdk);
        sdk[createMethod].mockReturnValue(element);
        sdk.loadActions.mockReturnValue(loadActions.promise);
        actions.getSession.mockReturnValue(session);

        let onChange: (nextSession: typeof session) => void = () => {
          throw new Error('The SDK change listener has not been attached');
        };
        sdk.on.mockImplementation((event, listener) => {
          if (event === 'change') {
            onChange = listener;
          }
        });

        return {
          stripe,
          sdk,
          element,
          session,
          loadActions,
          finishLoading: () => loadActions.resolve({type: 'success', actions}),
          changeSession: () => onChange(session),
        };
      };

      afterEach(() => {
        jest.restoreAllMocks();
      });

      describe.each([false, true])('StrictMode: %s', (strictMode) => {
        const Wrapper = strictMode ? React.StrictMode : React.Fragment;

        it.each(['sync', 'async'])(
          'skips SDK-only renders on session updates with %s Stripe',
          async (stripeMode) => {
            const {
              stripe,
              sdk,
              element,
              session,
              finishLoading,
              changeSession,
            } = setup();
            const stripePromise = makeDeferred();
            // This spy relies on ts-jest's CommonJS import property lookups.
            // Native ESM tests would need a different render probe.
            const contextHook = jest.spyOn(
              CheckoutContextModule,
              'useElementsOrCheckoutContextWithUseCase'
            );
            // Count actual Element renders, not just its parent's renders.
            const elementRenderCount = () =>
              contextHook.mock.calls.filter(([useCase]) =>
                useCase.startsWith('mounts ')
              ).length;
            const stripeRender = jest.fn();
            const StripeConsumer = React.memo(() => {
              stripeRender(useStripe());
              return null;
            });
            StripeConsumer.displayName = 'StripeConsumer';
            const SessionConsumer = () => {
              const result = useCheckout();
              const legacyResult = CheckoutContextModule.useCheckout();
              return (
                <>
                  <span data-testid="session">
                    {result.type === 'success'
                      ? result.checkout.currency
                      : result.type}
                  </span>
                  <span data-testid="legacy-session">
                    {legacyResult.type === 'success'
                      ? legacyResult.checkout.currency
                      : legacyResult.type}
                  </span>
                </>
              );
            };

            const view = render(
              <Wrapper>
                <Provider
                  stripe={
                    stripeMode === 'sync' ? stripe : stripePromise.promise
                  }
                  options={providerOptions}
                >
                  <Element />
                  <StripeConsumer />
                  <SessionConsumer />
                </Provider>
              </Wrapper>
            );

            if (stripeMode === 'async') {
              expect(stripeRender).toHaveBeenLastCalledWith(null);
              expect(element.mount).not.toHaveBeenCalled();
              await act(() => stripePromise.resolve(stripe));
            }

            // The Element must mount as soon as the SDK exists, without waiting
            // for loadActions to publish the first session.
            expect(element.mount).toHaveBeenCalledTimes(1);
            expect(stripeRender).toHaveBeenLastCalledWith(stripe);
            expect(view.getByTestId('session')).toHaveTextContent('loading');
            const initialElementRenders = elementRenderCount();
            const initialStripeRenders = stripeRender.mock.calls.length;

            await act(finishLoading);
            expect(view.getByTestId('session')).toHaveTextContent('usd');
            expect(view.getByTestId('legacy-session')).toHaveTextContent('usd');
            expect(elementRenderCount()).toBe(initialElementRenders);
            expect(stripeRender).toHaveBeenCalledTimes(initialStripeRenders);

            act(() => {
              // Session consumers must update even when the SDK reuses the object.
              session.currency = 'eur';
              changeSession();
            });
            expect(view.getByTestId('session')).toHaveTextContent('eur');
            expect(view.getByTestId('legacy-session')).toHaveTextContent('eur');
            expect(elementRenderCount()).toBe(initialElementRenders);
            expect(stripeRender).toHaveBeenCalledTimes(initialStripeRenders);
            expect(sdk[createMethod]).toHaveBeenCalledTimes(1);
            expect(element.mount).toHaveBeenCalledTimes(1);
            expect(element.update).not.toHaveBeenCalled();

            view.unmount();
            expect(element.destroy).toHaveBeenCalledTimes(1);
          }
        );

        it('still updates Element options and callbacks after a session change', async () => {
          const {stripe, element, finishLoading, changeSession} = setup();
          const onChange = jest.fn();
          const nextOnChange = jest.fn();
          let onElementChange: (event: unknown) => void = () => {
            throw new Error(
              'The Element change listener has not been attached'
            );
          };
          element.on.mockImplementation((event, listener) => {
            if (event === 'change') {
              onElementChange = listener;
            }
          });
          const tree = (
            options: typeof initialOptions | typeof updatedOptions,
            callback: typeof onChange
          ) => (
            <Wrapper>
              <Provider stripe={stripe} options={providerOptions}>
                <Element options={options} onChange={callback} />
              </Provider>
            </Wrapper>
          );
          const view = render(tree(initialOptions, onChange));
          await act(finishLoading);
          act(changeSession);

          const initialSubscriptions = element.on.mock.calls.length;
          act(() => onElementChange({complete: false}));
          expect(onChange).toHaveBeenCalledWith({complete: false});

          view.rerender(tree(updatedOptions, nextOnChange));
          expect(element.update).toHaveBeenCalledWith(updatedOptions);
          act(() => onElementChange({complete: true}));
          expect(nextOnChange).toHaveBeenCalledWith({complete: true});
          expect(onChange).toHaveBeenCalledTimes(1);
          expect(element.on).toHaveBeenCalledTimes(initialSubscriptions);
          expect(element.off).not.toHaveBeenCalled();
          expect(element.mount).toHaveBeenCalledTimes(1);
        });

        it('keeps Stripe available but does not create new Elements after an initialization error', async () => {
          const {stripe, sdk, element, loadActions} = setup();
          const stripeRender = jest.fn();
          const StripeConsumer = () => {
            stripeRender(useStripe());
            return null;
          };
          const SessionConsumer = () => <span>{useCheckout().type}</span>;
          const tree = (showConsumers: boolean) => (
            <Wrapper>
              <Provider stripe={stripe} options={providerOptions}>
                <SessionConsumer />
                {showConsumers && (
                  <>
                    <StripeConsumer />
                    <Element />
                  </>
                )}
              </Provider>
            </Wrapper>
          );
          const view = render(tree(false));
          await act(() =>
            loadActions.reject(new Error('Unable to load checkout'))
          );
          expect(view.getByText('error')).toBeInTheDocument();

          view.rerender(tree(true));
          expect(stripeRender).toHaveBeenLastCalledWith(stripe);
          expect(sdk[createMethod]).not.toHaveBeenCalled();
          expect(element.mount).not.toHaveBeenCalled();
        });
      });

      it('renders the server wrapper without initializing a supplied Stripe instance', () => {
        const {stripe} = setup();
        const ServerElement = createElementComponent(elementType, true);
        const stripeRender = jest.fn();
        const StripeConsumer = () => {
          stripeRender(useStripe());
          return null;
        };
        expect(
          renderToString(
            <Provider stripe={stripe} options={providerOptions}>
              <ServerElement id="checkout-element" />
              <StripeConsumer />
            </Provider>
          )
        ).toContain('<div id="checkout-element"></div>');
        expect(stripeRender).toHaveBeenLastCalledWith(null);
        expect(stripe[initMethod]).not.toHaveBeenCalled();
      });

      it.each(['stripe', 'element'])(
        'rejects mixed providers for %s consumers even before initialization',
        (consumer) => {
          jest.spyOn(console, 'error').mockImplementation(() => {});
          const StripeConsumer = () => {
            useStripe();
            return null;
          };
          expect(() =>
            render(
              <Elements stripe={null}>
                <Provider stripe={null} options={providerOptions}>
                  {consumer === 'stripe' ? <StripeConsumer /> : <Element />}
                </Provider>
              </Elements>
            )
          ).toThrow('in both a checkout provider and <Elements> provider');
        }
      );
    });
  }
);

import React from 'react';
import {render} from '@testing-library/react';
import {FinancialAccountDisclosure} from './FinancialAccountDisclosure';
import {StripeErrorType} from '@stripe/stripe-js';
import {mockStripe as baseMockStripe} from '../../test/mocks';

const apiError: StripeErrorType = 'api_error';

const mockSuccessfulStripeJsCall = () => {
  return {
    ...baseMockStripe(),
    createFinancialAccountDisclosure: jest.fn(() =>
      Promise.resolve({
        htmlElement: document.createElement('div'),
      })
    ),
  };
};

const mockStripeJsWithError = () => {
  return {
    ...baseMockStripe(),
    createFinancialAccountDisclosure: jest.fn(() =>
      Promise.resolve({
        error: {
          type: apiError,
          message: 'This is a test error',
        },
      })
    ),
  };
};

describe('FinancialAccountDisclosure', () => {
  let mockStripe: any;

  beforeEach(() => {
    mockStripe = mockSuccessfulStripeJsCall();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should render', () => {
    render(<FinancialAccountDisclosure stripe={mockStripe} />);
  });

  it('should render with options', () => {
    const options = {
      businessName: 'Test Business',
      learnMoreLink: 'https://test.com',
    };
    render(
      <FinancialAccountDisclosure stripe={mockStripe} options={options} />
    );
  });

  it('should render when there is an error', () => {
    mockStripe = mockStripeJsWithError();
    render(<FinancialAccountDisclosure stripe={mockStripe} />);
  });

  it('should render with an onLoad callback', async () => {
    const onLoad = jest.fn();
    render(<FinancialAccountDisclosure stripe={mockStripe} onLoad={onLoad} />);
    await new Promise((resolve) => setTimeout(resolve, 0));
    expect(onLoad).toHaveBeenCalled();
  });

  it('should not call onLoad if there is an error', async () => {
    const onLoad = jest.fn();
    mockStripe = mockStripeJsWithError();
    render(<FinancialAccountDisclosure stripe={mockStripe} onLoad={onLoad} />);
    await new Promise((resolve) => setTimeout(resolve, 0));
    expect(onLoad).not.toHaveBeenCalled();
  });

  it('should render with an onError callback', async () => {
    const onError = jest.fn();
    mockStripe = mockStripeJsWithError();
    render(
      <FinancialAccountDisclosure stripe={mockStripe} onError={onError} />
    );
    await new Promise((resolve) => setTimeout(resolve, 0));
    expect(onError).toHaveBeenCalled();
  });

  it('should not call onError if there is no error', async () => {
    const onError = jest.fn();
    render(
      <FinancialAccountDisclosure stripe={mockStripe} onError={onError} />
    );
    await new Promise((resolve) => setTimeout(resolve, 0));
    expect(onError).not.toHaveBeenCalled();
  });
});

import * as stripeJs from '@stripe/stripe-js';
import React, {FunctionComponent} from 'react';
import {parseStripeProp} from '../utils/parseStripeProp';
import {registerWithStripeJs} from '../utils/registerWithStripeJs';
import {StripeError} from '@stripe/stripe-js';
import {usePrevious} from '../utils/usePrevious';

interface FinancialAccountDisclosureProps {
  /**
   * A [Stripe object](https://stripe.com/docs/js/initializing) or a `Promise` resolving to a `Stripe` object.
   * The easiest way to initialize a `Stripe` object is with the the [Stripe.js wrapper module](https://github.com/stripe/stripe-js/blob/master/README.md#readme).
   * Once this prop has been set, it can not be changed.
   *
   * You can also pass in `null` or a `Promise` resolving to `null` if you are performing an initial server-side render or when generating a static site.
   */
  stripe: PromiseLike<stripeJs.Stripe | null> | stripeJs.Stripe | null;

  /**
   * Callback function called after the disclosure content loads.
   */
  onLoad?: () => void;

  /**
   * Callback function called when an error occurs during disclosure creation.
   */
  onError?: (error: StripeError) => void;

  /**
   * Optional Financial Account Disclosure configuration options.
   *
   * businessName: The name of your business as you would like it to appear in the disclosure. If not provided, the business name will be inferred from the Stripe account.
   * learnMoreLink: A supplemental link to for your users to learn more about Financial Accounts for platforms or any other relevant information included in the disclosure.
   */
  options?: {
    businessName?: string;
    learnMoreLink?: string;
  };
}

export const FinancialAccountDisclosure: FunctionComponent<
  FinancialAccountDisclosureProps
> = ({stripe: rawStripeProp, onLoad, onError, options}) => {
  const businessName = options?.businessName;
  const learnMoreLink = options?.learnMoreLink;

  const containerRef = React.useRef<HTMLDivElement>(null);
  const parsed = React.useMemo(
    () => parseStripeProp(rawStripeProp),
    [rawStripeProp]
  );
  const [stripeState, setStripeState] = React.useState<stripeJs.Stripe | null>(
    parsed.tag === 'sync' ? parsed.stripe : null
  );

  React.useEffect(() => {
    let isMounted = true;

    if (parsed.tag === 'async') {
      parsed.stripePromise.then((stripePromise: stripeJs.Stripe | null) => {
        if (stripePromise && isMounted) {
          setStripeState(stripePromise);
        }
      });
    } else if (parsed.tag === 'sync') {
      setStripeState(parsed.stripe);
    }

    return () => {
      isMounted = false;
    };
  }, [parsed]);

  // Warn on changes to stripe prop
  const prevStripe = usePrevious(rawStripeProp);
  React.useEffect(() => {
    if (prevStripe !== null && prevStripe !== rawStripeProp) {
      console.warn(
        'Unsupported prop change on FinancialAccountDisclosure: You cannot change the `stripe` prop after setting it.'
      );
    }
  }, [prevStripe, rawStripeProp]);

  // Attach react-stripe-js version to stripe.js instance
  React.useEffect(() => {
    registerWithStripeJs(stripeState);
  }, [stripeState]);

  React.useEffect(() => {
    const createDisclosure = async () => {
      if (!stripeState || !containerRef.current) {
        return;
      }

      const {htmlElement: disclosureContent, error} = await (
        stripeState as any
      ).createFinancialAccountDisclosure({
        businessName,
        learnMoreLink,
      });

      if (error && onError) {
        onError(error);
      } else if (disclosureContent) {
        const container = containerRef.current;
        container.innerHTML = '';
        container.appendChild(disclosureContent);
        if (onLoad) {
          onLoad();
        }
      }
    };

    createDisclosure();
  }, [stripeState, businessName, learnMoreLink, onLoad, onError]);

  return React.createElement('div', {ref: containerRef});
};

# React Stripe.js

React components for
[Stripe.js and Elements](https://stripe.com/docs/stripe-js).

[![npm version](https://img.shields.io/npm/v/@stripe/react-stripe-js.svg?style=flat-square)](https://www.npmjs.com/package/@stripe/react-stripe-js)

## Requirements

The minimum supported version of React is v16.8. If you use an older version,
upgrade React to use this library. If you prefer not to upgrade your React
version, we recommend using legacy
[`react-stripe-elements`](https://github.com/stripe/react-stripe-elements).

## Getting started

- [Build a custom checkout page using the Checkout Sessions API](https://docs.stripe.com/payments/accept-a-payment?payment-ui=elements&api-integration=checkout)
- [Add React Stripe.js to your React app](https://stripe.com/docs/stripe-js/react#setup)
- [Try it out using CodeSandbox](https://codesandbox.io/s/react-stripe-official-q1loc?fontsize=14&hidenavigation=1&theme=dark)

## Documentation

- [React Stripe.js reference](https://stripe.com/docs/stripe-js/react)
- [Migrate from `react-stripe-elements`](docs/migrating.md)
- [Legacy `react-stripe-elements` docs](https://github.com/stripe/react-stripe-elements/#react-stripe-elements)
- [Examples](examples)

## Build a custom checkout page

For a new custom checkout page, we recommend the
[Checkout Sessions API](https://docs.stripe.com/payments/accept-a-payment?payment-ui=elements&api-integration=checkout)
with `ui_mode: 'elements'`. This lets you combine Stripe Elements with your own
React layout while Checkout Sessions manages the checkout state. If you want to
own every part of your checkout, the lower-level
[Payment Intents API](https://docs.stripe.com/payments/accept-a-payment?payment-ui=elements&api-integration=payment-intents)
provides more fine-grained control, but requires significantly more code and
ongoing maintenance.

First, install React Stripe.js and
[Stripe.js](https://github.com/stripe/stripe-js).

```sh
npm install @stripe/react-stripe-js @stripe/stripe-js
```

Create a Checkout Session on your server using trusted product and pricing data,
then return its client secret:

```js
// POST /create-checkout-session
const session = await stripe.checkout.sessions.create({
  ui_mode: 'elements',
  mode: 'payment',
  return_url: 'https://example.com/order/123/complete',
  line_items: [
    {
      price_data: {
        currency: 'usd',
        product_data: {name: 'T-shirt'},
        unit_amount: 1099,
      },
      quantity: 1,
    },
  ],
});

if (!session.client_secret) {
  throw new Error('Checkout Session is missing a client secret.');
}

res.json({clientSecret: [REDACTED]});
```

Client:

```jsx
import React, {useState} from 'react';
import {createRoot} from 'react-dom/client';
import {loadStripe} from '@stripe/stripe-js';
import {
  PaymentElement,
  CheckoutElementsProvider,
  useCheckoutElements,
} from '@stripe/react-stripe-js/checkout';

const CheckoutForm = () => {
  const result = useCheckoutElements();
  const [errorMessage, setErrorMessage] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (result.type !== 'success' || !result.checkout.canConfirm) {
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);

    try {
      const confirmResult = await result.checkout.confirm({
        returnUrl: 'https://example.com/order/123/complete',
      });

      if (confirmResult.type === 'error') {
        setErrorMessage(confirmResult.error.message);
      }
    } catch (error) {
      setErrorMessage(
        error instanceof Error ? error.message : 'An unexpected error occurred.'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  if (result.type === 'loading') {
    return <div>Loading checkout...</div>;
  }

  if (result.type === 'error') {
    return <div>{result.error.message}</div>;
  }

  const {checkout} = result;

  return (
    <>
      <ul>
        {checkout.lineItems.map((lineItem) => (
          <li key={lineItem.id}>
            {lineItem.name}: {lineItem.total.amount}
          </li>
        ))}
      </ul>
      <p>Total: {checkout.total.total.amount}</p>
      <form onSubmit={handleSubmit}>
        <PaymentElement />
        <button type="submit" disabled={!checkout.canConfirm || isSubmitting}>
          {isSubmitting ? 'Processing...' : 'Pay'}
        </button>
        {errorMessage && <div>{errorMessage}</div>}
      </form>
    </>
  );
};

// Use the publishable key for the same account that created the Checkout Session.
const stripePromise = loadStripe('pk_test_...');

const clientSecretPromise = fetch('/create-checkout-session', {
  method: 'POST',
}).then(async (response) => {
  const body = await response.json();

  if (!response.ok) {
    throw new Error(body.error ?? 'Unable to create a Checkout Session.');
  }

  return body.clientSecret;
});

const options = {
  clientSecret: [REDACTED],
  elementsOptions: {
    appearance: {
      theme: 'stripe',
    },
  },
};

const App = () => (
  <CheckoutElementsProvider stripe={stripePromise} options={options}>
    <CheckoutForm />
  </CheckoutElementsProvider>
);

createRoot(document.getElementById('root')).render(<App />);
```

### TypeScript support

React Stripe.js is packaged with TypeScript declarations. Some types are pulled
from [`@stripe/stripe-js`](https://github.com/stripe/stripe-js)—be sure to add
`@stripe/stripe-js` as a dependency to your project for full TypeScript support.

Typings in React Stripe.js follow the same
[versioning policy](https://github.com/stripe/stripe-js#typescript-support) as
`@stripe/stripe-js`.

### Contributing

This project is maintained by Stripe and does not accept external pull requests.
If you have feedback or ideas, please
[open an issue](https://github.com/stripe/react-stripe-js/issues/new).

const makeDeferred = <T extends any>() => {
  let resolve!: (arg: T) => void;
  let reject!: (arg: any) => void;
  const promise: Promise<T> = new Promise((res: any, rej: any) => {
    resolve = jest.fn(res);
    reject = jest.fn(rej);
  });
  return {
    resolve: async (arg: T) => {
      resolve(arg);
      await new Promise(process.nextTick);
    },
    reject: async (failure: any) => {
      reject(failure);
      await new Promise(process.nextTick);
    },
    promise,
    getPromise: jest.fn(() => promise),
  };
};
export default makeDeferred;

export const mockElement = () => ({
  mount: jest.fn(),
  destroy: jest.fn(),
  on: jest.fn(),
  update: jest.fn(),
});

export const mockElements = () => {
  const elements = {};
  return {
    create: jest.fn((type) => {
      elements[type] = mockElement();
      return elements[type];
    }),
    getElement: jest.fn((componentOrType) => {
      const type = componentOrType.__elementType || componentOrType;
      return elements[type] || null;
    }),
    update: jest.fn(),
  };
};

export const mockCheckoutSession = () => {
  return {
    lineItems: [],
    currency: 'usd',
    shippingOptions: [],
    total: {
      subtotal: 1099,
      taxExclusive: 0,
      taxInclusive: 0,
      shippingRate: 0,
      discount: 0,
      total: 1099,
    },
    confirmationRequirements: [],
    canConfirm: true,
  };
};

export const mockCheckoutActions = () => {
  return {
    getSession: jest.fn(() => mockCheckoutSession()),
    applyPromotionCode: jest.fn(),
    removePromotionCode: jest.fn(),
    updateShippingAddress: jest.fn(),
    updateBillingAddress: jest.fn(),
    updatePhoneNumber: jest.fn(),
    updateEmail: jest.fn(),
    updateLineItemQuantity: jest.fn(),
    updateTaxIdInfo: jest.fn(),
    updateShippingOption: jest.fn(),
    confirm: jest.fn(),
    runServerUpdate: jest.fn(),
  };
